class ConnectApps(SyncAPIResource):

    def list(
        self,
        *,
        cursor: Union[str, NotGiven] = NOT_GIVEN,
        limit: Union[int, NotGiven] = NOT_GIVEN,
        extra_headers: Optional[Mapping[str, str]] = None,
        extra_query: Optional[Mapping[str, object]] = None,
        timeout: Optional[float] = None,
    ) -> SyncCursorPage[C.App]:
        """List the organisation's apps

        The console lists the apps of the organisation it names. An API key lists only the app of its own project.

        `GET /v1/connect/apps`, scope `connect.read`.
        """
        return self._client._request_page(
            OPERATIONS["connect.apps.list"],
            query={"cursor": cursor, "limit": limit},
            options=RequestOptions(extra_headers=extra_headers, extra_query=extra_query, timeout=timeout),
            item_type=C.App,
            list_type=C.AppList,
        )

    def get(
        self,
        app_id: str,
        *,
        extra_headers: Optional[Mapping[str, str]] = None,
        extra_query: Optional[Mapping[str, object]] = None,
        timeout: Optional[float] = None,
    ) -> C.App:
        """Get an app

        The console reads any app of the organisation it names. An API key reads only the app of its own project; any other app answers 404.

        `GET /v1/connect/apps/{app_id}`, scope `connect.read`.
        """
        return cast(
            C.App,
            self._client._request(
                OPERATIONS["connect.apps.get"],
                path={"app_id": app_id},
                options=RequestOptions(extra_headers=extra_headers, extra_query=extra_query, timeout=timeout),
                cast_to=C.App,
            ),
        )

    def update(
        self,
        app_id: str,
        *,
        name: Union[str, NotGiven] = NOT_GIVEN,
        vendor_name: Union[str, NotGiven] = NOT_GIVEN,
        description: Union[Optional[str], NotGiven] = NOT_GIVEN,
        logo_url: Union[Optional[str], NotGiven] = NOT_GIVEN,
        homepage_url: Union[Optional[str], NotGiven] = NOT_GIVEN,
        privacy_url: Union[Optional[str], NotGiven] = NOT_GIVEN,
        avv_url: Union[Optional[str], NotGiven] = NOT_GIVEN,
        redirect_uris: Union[Sequence[str], NotGiven] = NOT_GIVEN,
        jwks_uri: Union[Optional[str], NotGiven] = NOT_GIVEN,
        extra_headers: Optional[Mapping[str, str]] = None,
        extra_query: Optional[Mapping[str, object]] = None,
        extra_body: Optional[Mapping[str, object]] = None,
        timeout: Optional[float] = None,
    ) -> C.App:
        """Change an app

        An API key of the app's own project changes the texts the practice admin reads, the links, the redirect URIs and the JWKS URL. At an app with a live project only a key of that live project does: a test key answers 403 `forbidden` with `reason: test_key`, a key of another project 404. The JWKS URL must be https on a host whose every address is public. The scopes, the verbs, the projects and the status change in the console only. An access token cannot call it.

        `PATCH /v1/connect/apps/{app_id}`, scope `connect.setup`.
        """
        return cast(
            C.App,
            self._client._request(
                OPERATIONS["connect.apps.update"],
                path={"app_id": app_id},
                body={"name": name, "vendor_name": vendor_name, "description": description, "logo_url": logo_url, "homepage_url": homepage_url, "privacy_url": privacy_url, "avv_url": avv_url, "redirect_uris": redirect_uris, "jwks_uri": jwks_uri},
                options=RequestOptions(extra_headers=extra_headers, extra_query=extra_query, timeout=timeout, extra_body=extra_body),
                cast_to=C.App,
            ),
        )

    def add_key(
        self,
        app_id: str,
        *,
        jwk: Union[Mapping[str, Any], NotGiven] = NOT_GIVEN,
        pem: Union[str, NotGiven] = NOT_GIVEN,
        kid: Union[str, NotGiven] = NOT_GIVEN,
        idempotency_key: Optional[str] = None,
        extra_headers: Optional[Mapping[str, str]] = None,
        extra_query: Optional[Mapping[str, object]] = None,
        extra_body: Optional[Mapping[str, object]] = None,
        timeout: Optional[float] = None,
    ) -> C.AppKey:
        """Add a public key for client authentication

        A public key for `private_key_jwt` (RFC 7523): an EC P-256 key (ES256) or an Ed25519 key (EdDSA), as a JWK or as a PEM (SPKI). Never a private key: a key with a private part answers 400. Without `kid` the key id is the JWK thumbprint (RFC 7638). An app holds up to 5 keys. Add the new key, switch your signer, then delete the old key. Only a key of the app's own project adds or deletes keys, and at an app with a live project only a key of that live project (else 403 `test_key`, or 404 for another project), or the console.

        `POST /v1/connect/apps/{app_id}/keys`, scope `connect.setup`.
        """
        return cast(
            C.AppKey,
            self._client._request(
                OPERATIONS["connect.apps.addKey"],
                path={"app_id": app_id},
                body={"jwk": jwk, "pem": pem, "kid": kid},
                options=RequestOptions(idempotency_key=idempotency_key, extra_headers=extra_headers, extra_query=extra_query, timeout=timeout, extra_body=extra_body),
                cast_to=C.AppKey,
            ),
        )

    def delete_key(
        self,
        app_id: str,
        kid: str,
        *,
        extra_headers: Optional[Mapping[str, str]] = None,
        extra_query: Optional[Mapping[str, object]] = None,
        timeout: Optional[float] = None,
    ) -> None:
        """Delete a key of an app

        Assertions signed with the key fail from now on. Access tokens already issued keep working until they expire (15 minutes).

        `DELETE /v1/connect/apps/{app_id}/keys/{kid}`, scope `connect.setup`.
        """
        return cast(
            None,
            self._client._request(
                OPERATIONS["connect.apps.deleteKey"],
                path={"app_id": app_id, "kid": kid},
                options=RequestOptions(extra_headers=extra_headers, extra_query=extra_query, timeout=timeout),
                cast_to=None,
            ),
        )


