class ConnectTransfers(SyncAPIResource):

    def list(
        self,
        *,
        site_id: Union[str, NotGiven] = NOT_GIVEN,
        status: Union[C.TransferStatus, NotGiven] = NOT_GIVEN,
        cursor: Union[str, NotGiven] = NOT_GIVEN,
        limit: Union[int, NotGiven] = NOT_GIVEN,
        extra_headers: Optional[Mapping[str, str]] = None,
        extra_query: Optional[Mapping[str, object]] = None,
        timeout: Optional[float] = None,
    ) -> SyncCursorPage[C.Transfer]:
        """List transfers

        `GET /v1/connect/transfers`, scope `connect.read`.
        """
        return self._client._request_page(
            OPERATIONS["connect.transfers.list"],
            query={"site_id": site_id, "status": status, "cursor": cursor, "limit": limit},
            options=RequestOptions(extra_headers=extra_headers, extra_query=extra_query, timeout=timeout),
            item_type=C.Transfer,
            list_type=C.TransferList,
        )

    def create(
        self,
        *,
        plan_id: str,
        release: Union[C.ReleaseInput, Mapping[str, Any]],
        idempotency_key: Optional[str] = None,
        extra_headers: Optional[Mapping[str, str]] = None,
        extra_query: Optional[Mapping[str, object]] = None,
        extra_body: Optional[Mapping[str, object]] = None,
        timeout: Optional[float] = None,
    ) -> C.Transfer:
        """Release a plan and send it

        Takes a plan and the release of the person who reviewed it. Answers 202 at once; the hub delivers when online. Poll `transfers.get` or read events. Checks: licence, grant, role, practitioner link, plan age and adapter version, dedupe.

        `POST /v1/connect/transfers`, scope `connect.transfer`, answers hold patient data, metered as `connect.transfer`, Idempotency-Key required (the SDK makes one).
        """
        return cast(
            C.Transfer,
            self._client._request(
                OPERATIONS["connect.transfers.create"],
                body={"plan_id": plan_id, "release": release},
                options=RequestOptions(idempotency_key=idempotency_key, extra_headers=extra_headers, extra_query=extra_query, timeout=timeout, extra_body=extra_body),
                cast_to=C.Transfer,
            ),
        )

    def get(
        self,
        transfer_id: str,
        *,
        extra_headers: Optional[Mapping[str, str]] = None,
        extra_query: Optional[Mapping[str, object]] = None,
        timeout: Optional[float] = None,
    ) -> C.Transfer:
        """Get the status of a transfer

        `GET /v1/connect/transfers/{transfer_id}`, scope `connect.read`.
        """
        return cast(
            C.Transfer,
            self._client._request(
                OPERATIONS["connect.transfers.get"],
                path={"transfer_id": transfer_id},
                options=RequestOptions(extra_headers=extra_headers, extra_query=extra_query, timeout=timeout),
                cast_to=C.Transfer,
            ),
        )

    def resolve(
        self,
        transfer_id: str,
        *,
        action: Union[Literal["mark_done", "resend", "mark_failed"], str],
        resolved_by: Union[C.MemberRef, Mapping[str, Any]],
        note: Union[str, NotGiven] = NOT_GIVEN,
        idempotency_key: Optional[str] = None,
        extra_headers: Optional[Mapping[str, str]] = None,
        extra_query: Optional[Mapping[str, object]] = None,
        extra_body: Optional[Mapping[str, object]] = None,
        timeout: Optional[float] = None,
    ) -> C.Transfer:
        """Settle an `in_doubt` or `failed` transfer

        A person checked the target system: `mark_done` if the entry is there, `resend` to send it again, `mark_failed` to give it up. The answer is the settled transfer, or for `resend` the new one. A `failed` transfer is parked on the hub too: `mark_done` and `mark_failed` unpark it there; it has no release any more, so `resend` answers 409 and the note is released again. The PDFs of the plan (`uploads.create`) stay until the transfer's `expires_at`; a `resend` after they are gone answers 409 `uploads_gone`, and the transfer stays as it was. `resolved_by` is an active doctor or site admin; another role gets 403 `forbidden` with `reason` `role`.

        `POST /v1/connect/transfers/{transfer_id}/resolve`, scope `connect.transfer`.
        """
        return cast(
            C.Transfer,
            self._client._request(
                OPERATIONS["connect.transfers.resolve"],
                path={"transfer_id": transfer_id},
                body={"action": action, "resolved_by": resolved_by, "note": note},
                options=RequestOptions(idempotency_key=idempotency_key, extra_headers=extra_headers, extra_query=extra_query, timeout=timeout, extra_body=extra_body),
                cast_to=C.Transfer,
            ),
        )

    def wait(
        self,
        transfer_id: str,
        *,
        until: Optional[Callable[[C.Transfer], bool]] = None,
        timeout: float = 120.0,
        interval: float = 1.0,
        on_update: Optional[Callable[[C.Transfer], None]] = None,
    ) -> C.Transfer:
        """Helper, no API operation: reads the transfer until it is final or in_doubt, or until the `until` check holds.
"""
        return wait_for_transfer(self.get, transfer_id, until=until, timeout=timeout, interval=interval, on_update=on_update)


class ConnectEvents(SyncAPIResource):

    def list(
        self,
        *,
        site_id: Union[str, NotGiven] = NOT_GIVEN,
        types: Union[Sequence[C.EventType], NotGiven] = NOT_GIVEN,
        cursor: Union[str, NotGiven] = NOT_GIVEN,
        limit: Union[int, NotGiven] = NOT_GIVEN,
        extra_headers: Optional[Mapping[str, str]] = None,
        extra_query: Optional[Mapping[str, object]] = None,
        timeout: Optional[float] = None,
    ) -> SyncCursorPage[C.Event]:
        """Poll events

        Poll with the last cursor. Webhooks come later through the API platform.

        `GET /v1/connect/events`, scope `connect.read`.
        """
        return self._client._request_page(
            OPERATIONS["connect.events.list"],
            query={"site_id": site_id, "types": types, "cursor": cursor, "limit": limit},
            options=RequestOptions(extra_headers=extra_headers, extra_query=extra_query, timeout=timeout),
            item_type=C.Event,
            list_type=C.EventList,
        )

    def poll(
        self,
        *,
        site_id: Union[str, NotGiven] = NOT_GIVEN,
        types: Union[Sequence[str], NotGiven] = NOT_GIVEN,
        cursor: Union[Optional[str], NotGiven] = NOT_GIVEN,
        limit: Union[int, NotGiven] = NOT_GIVEN,
        interval: float = 5.0,
        stop: Optional[threading.Event] = None,
    ) -> Iterator[SyncCursorPage[C.Event]]:
        """Helper, no API operation: polls events.list from a cursor on and yields each page with events. Save next_cursor once a page is handled.
"""
        def list_page(next_cursor: Optional[str]) -> SyncCursorPage[C.Event]:
            return self.list(site_id=site_id, types=types, limit=limit, cursor=next_cursor if next_cursor is not None else NOT_GIVEN)

        return poll_events(list_page, None if isinstance(cursor, NotGiven) else cursor, interval=interval, stop=stop)


